// Helper functions for creating standardized responses

/**
 * Create a standardized success response envelope.
 * @param data - Payload data.
 * @param message - Optional human readable message.
 * @returns SuccessResponse<T>
 */
export function createStandardSuccessResponse<T>(
  data: T,
  message?: string
): SuccessResponse<T> {
  return {
    success: true,
    data,
    message,
    timestamp: new Date().toISOString(),
  };
}

/**
 * Create a standardized error response envelope.
 * @param error - Error message.
 * @param type - Optional classification of error.
 * @param code - Optional error code.
 * @returns ErrorResponse
 */
export function createStandardErrorResponse(
  error: string,
  type?: ErrorResponse["type"],
  code?: string
): ErrorResponse {
  return {
    success: false,
    error,
    type,
    code,
    timestamp: new Date().toISOString(),
  };
}

// Legacy aliases for backward compatibility
export const createSuccessResponse = createStandardSuccessResponse;
export const createErrorResponse = createStandardErrorResponse;

// Utility functions

/**
 * Safely formats a time string with validation for messaging timestamps
 * Returns a fallback value for invalid dates
 */
export function formatRelativeTime(
  dateString: string | null | undefined,
  fallback: string = "—"
): string {
  if (!dateString) {
    console.warn("formatRelativeTime: No dateString provided:", dateString);
    return fallback;
  }

  try {
    const date = new Date(dateString);

    // Check if the date is valid
    if (isNaN(date.getTime())) {
      console.warn(`Invalid date string received: ${dateString}`);
      return fallback;
    }

    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / (1000 * 60));
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

    if (diffMins < 1) {
      return "Just now";
    } else if (diffMins < 60) {
      return `${diffMins}m ago`;
    } else if (diffHours < 24) {
      return `${diffHours}h ago`;
    } else if (diffDays === 1) {
      return "Yesterday";
    } else if (diffDays < 7) {
      return `${diffDays}d ago`;
    } else {
      // For older messages, show the date
      return date.toLocaleDateString();
    }
  } catch (error) {
    console.error(`Error formatting relative time: ${dateString}`, error);
    return fallback;
  }
}
